\label{remark_asymptotics}
		Throughout the paper, we generally consider the asymptotics as one specific parameter tends to infinity. We emphasize for clarity that this does not rely on some underlying sequence of objects and values that depend on this parameter. So unless a value is explicitly mentioned to be fixed, the constants hidden by the asymptotics may never depend on such a value.

		For example, consider Theorem~\ref{theorem_simple} from Section \ref{subsection_results_simple}, where $m\to\infty$. The assumption $\Delta=O(m^{1/2}/(\log m)^2)$ simply means that we assume there exist constants $C,N>0$ such that $m\geq N$ implies $|\Delta|\leq Cm^{1/2}/(\log m)^2$, as defined by big O notation. Then the terms $O(\Delta/m)$ and $O(\mathscr{E})$ in the conclusion imply the existence of constants $C_1,N_1,C_2,N_2>0$ such that these terms are absolutely bounded by $C_1\Delta/m$ and $C_2\mathscr{E}$ if $m\geq N_1$ or $m\geq N_2$ respectively. Note that the constants $C_1,N_1,C_2,N_2$ may thus depend on $C$ and $N$, but not on anything else.

\label{definition_process_simple}
		Consider the vertex set $V=\{v_1,\ldots,v_n\}$, consider a degree sequence ${\boldsymbol{d}}=(d_1,\ldots,d_n)$ of non-negative integers with $2m:=d_1+\ldots+d_n>0$ even, and consider a set $X$ of forbidden edges.
		\begin{itemize}
			\item Start with no edges $E_0=\emptyset$.
			\item For $r=0,\ldots,m-1$, let $d_{i,r}$ denote the degree of vertex $v_i$ in $(V,E_r)$, and consider those pairs of vertices $v_i,v_j\in V$ with $i\neq j$, $d_{i,r}<d_i$, $d_{j,r}<d_j$, and $\{v_i,v_j\}\not\in E_r\cup X$.
			\begin{itemize}
				\item If no such pairs exist, let $E_{r+1}=E_r$.
				\item Otherwise, choose such a pair $v_i,v_j$ at random with probability proportional to $(d_i-d_{i,r})(d_j-d_{j,r})(1-\tfrac{d_id_j}{4m})$, and let $E_{r+1}=E_r\cup\{\{v_i,v_j\}\}$.
			\end{itemize}
			\item Finally, apply rejection sampling to sample $E=E_m$ with $m$ edges.
		\end{itemize}
		This guarantees that $(V,E)$ is a simple undirected graph with degree sequence ${\boldsymbol{d}}$ and with no edges from $X$.

\label{theorem_simple}
		Consider the iterative undirected graph process on $V$, ${\boldsymbol{d}}$, and $X$. Let $x_{\max}$ be the maximum degree in $(V,X)$, and let
		\begin{align}
			d_{\max}&:=\max\{d_1,\ldots,d_n\},
			\\\Delta&:=d_{\max}(d_{\max}+x_{\max}).
		\end{align}
		Consider the asymptotics as $m\to\infty$, and assume that $\Delta=O(m^{\sfrac12}/(\log m)^2)$. Then the probability of rejection is $O(\Delta/m)$. In particular, for $m$ large enough, there exists a simple undirected graph with degree sequence ${\boldsymbol{d}}$ and with no edges from $X$. Furthermore, any such graph is sampled with probability $(1+O(\mathscr{E}))\mathscr{P}$, where $\mathscr{E}:=\mathscr{E}(m,\Delta)$ and $$\mathscr{P}:=\exp(\tfrac12\lambda_{\boldsymbol{d}}+\tfrac14\lambda_{\boldsymbol{d}}^2+\mu_{{\boldsymbol{d}}}^{X})\frac1{(2m-1)!!}\prod_{i=1}^{n}d_i!,$$ which is asymptotically uniform. The total number of such graphs is thus $(1+O(\mathscr{E}))\mathscr{P}^{-1}$.

Consider the bipartite vertex set $V=A\cup B$ with $A=\{v_1,\ldots,v_n\}$ and $B=\{v_1',\ldots,v_{n'}'\}$, consider degree sequences ${\boldsymbol{d}}=(d_1,\ldots,d_n)$ and ${\boldsymbol{d}}'=(d_1',\ldots,d_{n'}')$ of non-negative integers with $m:=d_1+\ldots+d_n=d_1'+\ldots+d_{n'}'>0$, and consider a set $X$ of forbidden edges.
\begin{itemize}
	\item Start with no edges $E_0=\emptyset$.
	\item For $r=0,\ldots,m-1$, let $d_{i,r}$ and $d_{j,r}'$ denote the degrees of vertices $v_i$ and $v_j'$ in $(V,E_r)$, and consider those pairs of vertices $(v_i,v_j')\in A\times B$ with $d_{i,r}<d_i$, $d_{j,r}'<d_j'$, and $(v_i,v_j')\not\in E_r\cup X$.
	\begin{itemize}
		\item If no such pairs exist, let $E_{r+1}=E_r$.
		\item Otherwise, choose such a pair $(v_i,v_j')$ at random with probability proportional to $(d_i-d_{i,r})(d_j'-d_{j,r}')(1-\tfrac{d_id_j'}{2m})$, and let $E_{r+1}=E_r\cup\{(v_i,v_j')\}$.
	\end{itemize}
	\item Finally, apply rejection sampling to sample $E=E_m$ with $m$ edges.
\end{itemize}
This guarantees that $(V,E)$ is a simple bipartite graph with degree sequences ${\boldsymbol{d}}$ and ${\boldsymbol{d}}'$ on its parts and with no edges from $X$.

\label{theorem_bipartite}
		Consider the iterative bipartite graph process on $V$, ${\boldsymbol{d}}$, ${\boldsymbol{d}}'$, and $X$. Let $x_{\max}$ be the maximum degree in $(V,X)$, and let
		\begin{align}
			d_{\max}&:=\max\{d_1,\ldots,d_n,d_1',\ldots,d_{n'}'\},
			\\\Delta&:=d_{\max}(d_{\max}+x_{\max}).
		\end{align}
		Consider the asymptotics as $m\to\infty$, and assume that $\Delta=O(m^{\sfrac12}/(\log m)^2)$. Then the probability of rejection is $O(\Delta/m)$. In particular, for $m$ large enough, there exists a simple bipartite graph with degree sequences ${\boldsymbol{d}}$ and ${\boldsymbol{d}}'$ on its parts and with no edges from $X$. Furthermore, any such graph is sampled with probability $(1+O(\mathscr{E}))\mathscr{P}$, where $\mathscr{E}:=\mathscr{E}(m,\Delta)$ and $$\mathscr{P}:=\exp(\tfrac12\lambda_{\boldsymbol{d}}\lambda_{{\boldsymbol{d}}'}+\mu_{{\boldsymbol{d}},{\boldsymbol{d}}'}^{X})\frac1{m!}\prod_{i=1}^{n}d_i!\prod_{j=1}^{n'}d_j'!,$$ which is asymptotically uniform. The total number of such graphs is thus $(1+O(\mathscr{E}))\mathscr{P}^{-1}$.

\label{theorem_oriented}
		Consider the iterative oriented graph process on $V$, ${\boldsymbol{d}}$, ${\boldsymbol{d}}'$, and $X$. Let $x_{\max}$ be the maximum out- or in-degree in $(V,X)$, and let
		\begin{align}
			d_{\max}&:=\max\{d_1,\ldots,d_n,d_1',\ldots,d_{n}'\},
			\\\Delta&:=d_{\max}(d_{\max}+x_{\max}).
		\end{align}
		Consider the asymptotics as $m\to\infty$, and assume that $\Delta=O(m^{\sfrac12}/(\log m)^2)$. Then the probability of rejection is $O(\Delta/m)$. In particular, for $m$ large enough, there exists an oriented graph with out- and in-degree sequences ${\boldsymbol{d}}$ and ${\boldsymbol{d}}'$ and with no arcs from $X$. Furthermore, any such graph is sampled with probability $(1+O(\mathscr{E}))\mathscr{P}$, where $\mathscr{E}:=\mathscr{E}(m,\Delta)$ and $$\mathscr{P}:=\exp(\lambda_{{\boldsymbol{d}},{\boldsymbol{d}}'}+\tfrac12\lambda_{{\boldsymbol{d}},{\boldsymbol{d}}'}^2+\tfrac12\lambda_{{\boldsymbol{d}}}\lambda_{{\boldsymbol{d}}'}+\mu_{{\boldsymbol{d}},{\boldsymbol{d}}'}^{X})\frac1{m!}\prod_{i=1}^{n}d_i!d_i'!,$$ which is asymptotically uniform. The total number of such graphs is thus $(1+O(\mathscr{E}))\mathscr{P}^{-1}$.

\label{theorem_colored}
		Consider the iterative edge-colored graph process on $V$ and ${\boldsymbol{d}}^{(g)}$ and $X^{(g)}$ for $g=1,\ldots,\chi$. Let $x_{\max}^{(g)}$ be the maximum degree in $(V,X^{(g)})$, and let
		\begin{align}
			d_{\max}^{(g)}&:=\max\{d_1^{(g)},\ldots,d_n^{(g)}\},
			\\\Delta^{(g)}&:=d_{\max}^{(g)}\left(x_{\max}^{(g)}+\sum_{h=1}^{g}d_{\max}^{(h)}\right)+m^{(g)}\sum_{h=g+1}^{\chi}\frac{(d_{\max}^{(h)})^2}{m^{(h)}}.
		\end{align}
		Consider the asymptotics as $m_{\min}:=\min\{m^{(1)},\ldots,m^{(\chi)}\}\to\infty$, and assume that $\Delta^{(g)}=O((m^{(g)})^{\sfrac12}/(\log m^{(g)})^2)$ for $g=1,\ldots,\chi$. Then each iteration $g=1,\ldots,\chi$ has probability $O(\Delta^{(g)}/m^{(g)})$ of rejection. In particular, for $m_{\min}$ large enough, there exist edge-disjoint simple graphs for $g=1,\ldots,\chi$ with degree sequence ${\boldsymbol{d}}^{(g)}$ and with no edges from $X^{(g)}$. Furthermore, any such graphs are sampled with probability $e^{O(\mathscr{E})}\mathscr{P}$, where $\mathscr{E}:=\sum_{g=1}^{\chi}\mathscr{E}(m^{(g)},\Delta^{(g)})$ and
		\begin{align}
			\mathscr{P}&:=\exp\left(\sum_{g=1}^{\chi}\left(\tfrac12\lambda_{{\boldsymbol{d}}^{(g)}}+\tfrac14\lambda_{{\boldsymbol{d}}^{(g)}}^2+\tfrac12\sum_{h=g+1}^{\chi}\lambda_{{\boldsymbol{d}}^{(g)},{\boldsymbol{d}}^{(h)}}^2+\mu_{{\boldsymbol{d}}^{(g)}}^{X^{(g)}}\right)\right)
			\\&\quad\cdot\prod_{g=1}^{\chi}\left(\frac1{(2m^{(g)}-1)!!}\prod_{i=1}^{n}d_i^{(g)}!\right),
		\end{align}
		which is asymptotically uniform if $\mathscr{E}=o(1)$. The total number of such graphs is thus $e^{O(\mathscr{E})}\mathscr{P}^{-1}$.

\begin{align}
		d_{\max}^{(h)}&=O\left(\frac{(m^{(g)})^{\sfrac14}}{\chi^{\sfrac12}\log m^{(g)}}\right)\ \text{for}\ h\leq g,
		\\\frac{(d_{\max}^{(h)})^2}{m^{(h)}}&=O\left(\frac{(m^{(g)})^{-\sfrac12}}{\chi(\log m^{(g)})^2}\right)\ \text{for}\ h\geq g.
	\end{align}

\label{theorem_bipcol}
		Consider the iterative edge-colored graph process on $V$ and ${\boldsymbol{d}}^{(g)}$, ${\boldsymbol{d}}'^{(g)}$ and $X^{(g)}$ for $g=1,\ldots,\chi$. Let $x_{\max}^{(g)}$ be the maximum degree in $(V,X^{(g)})$, and let
		\begin{align}
			d_{\max}^{(g)}&:=\max\{d_1^{(g)},\ldots,d_n^{(g)},d_1'^{(g)},\ldots,d_{n'}'^{(g)}\},
			\\\Delta^{(g)}&:=d_{\max}^{(g)}\left(x_{\max}^{(g)}+\sum_{h=1}^{g}d_{\max}^{(h)}\right)+m^{(g)}\sum_{h=g+1}^{\chi}\frac{(d_{\max}^{(h)})^2}{m^{(h)}}.
		\end{align}
		Consider the asymptotics as $m_{\min}:=\min\{m^{(1)},\ldots,m^{(\chi)}\}\to\infty$, and assume that $\Delta^{(g)}=O((m^{(g)})^{\sfrac12}/(\log m^{(g)})^2)$ for $g=1,\ldots,\chi$. Then each iteration $g=1,\ldots,\chi$ has probability $O(\Delta^{(g)}/m^{(g)})$ of rejection. In particular, for $m_{\min}$ large enough, there exist edge-disjoint simple bipartite graphs for $g=1,\ldots,\chi$ with degree sequences ${\boldsymbol{d}}^{(g)}$ and ${\boldsymbol{d}}'^{(g)}$ on their parts and with no edges from $X^{(g)}$. Furthermore, any such graphs are sampled with probability $e^{O(\mathscr{E})}\mathscr{P}$, where $\mathscr{E}:=\sum_{g=1}^{\chi}\mathscr{E}(m^{(g)},\Delta^{(g)})$ and
		\begin{align}
			\mathscr{P}&:=\exp\Bigg(\sum_{g=1}^{\chi}\Bigg(\tfrac12\lambda_{{\boldsymbol{d}}^{(g)}}\lambda_{{\boldsymbol{d}}'^{(g)}}+\sum_{h=g+1}^{\chi}\lambda_{{\boldsymbol{d}}^{(g)},{\boldsymbol{d}}^{(h)}}\lambda_{{\boldsymbol{d}}'^{(g)},{\boldsymbol{d}}'^{(h)}}+\mu_{{\boldsymbol{d}}^{(g)},{\boldsymbol{d}}'^{(g)}}^{X^{(g)}}\Bigg)\Bigg)
			\\&\quad\cdot\prod_{g=1}^{\chi}\left(\frac1{m^{(g)}!}\prod_{i=1}^{n}d_i^{(g)}!\prod_{j=1}^{n'}d_j'^{(g)}!\right),
		\end{align}
		which is asymptotically uniform if $\mathscr{E}=o(1)$. The total number of such graphs is thus $e^{O(\mathscr{E})}\mathscr{P}^{-1}$.

\begin{align}
		d_{\max}^{(h)}&=O\left(\frac{(m^{(g)})^{\sfrac14}}{\chi^{\sfrac12}\log m^{(g)}}\right)\ \text{for}\ h\leq g,
		\\\frac{(d_{\max}^{(h)})^2}{m^{(h)}}&=O\left(\frac{(m^{(g)})^{-\sfrac12}}{\chi(\log m^{(g)})^2}\right)\ \text{for}\ h\geq g.
	\end{align}

\label{theorem_hyper}
		Consider the iterative hypergraph process on $V$, ${\boldsymbol{d}}$, ${\boldsymbol{d}}'$, and $X$. Let $$d_{\max}:=\max\{d_1,\ldots,d_n,d_1',\ldots,d_m'\},$$ and for $k\geq2$, let $c_k$ be the required number of hyperedges of cardinality $k$, and let $x_k$ be the number of hyperedges in $X$ of cardinality $k$. Define
		\begin{align}
			\rho_k&:=k!\binom{c_k}{2}\left(\frac{\lambda_{{\boldsymbol{d}}}}{s}\right)^k\leq\binom{c_k}{2}\left(\frac{k\lambda_{{\boldsymbol{d}}}}{s}\right)^k,
			\\\rho_X&:=\sum_{e\in X}\frac{c_{|e|}|e|!}{s^{|e|}}\prod_{v_i\in e}d_i\leq\sum_{k=2}^{d_{\max}}x_{k}c_{k}\left(\frac{kd_{\max}}{s}\right)^{k}.
		\end{align}
		Consider the asymptotics as $s\to\infty$, and assume that $d_{\max}=O(s^{\sfrac14}/\log s)$ and $\rho_2,\rho_X=o(1)$. Then the probability of rejection in the iterative bipartite graph process is $O(d_{\max}^2/s)$, and the probability of rejection afterwards is $O(\rho_2+\rho_3+\rho_X+1/s)$. In particular, for $s$ large enough, there exists a simple hypergraph with degree sequence ${\boldsymbol{d}}$ and with hyperedges not in $X$ with cardinalities matching ${\boldsymbol{d}}'$. Furthermore, any such hypergraph is sampled with probability $(1+O(\mathscr{E}+\rho_2+\rho_X))\mathscr{P}$, where $\mathscr{E}:=\mathscr{E}(s,d_{\max}^2)$ and $$\mathscr{P}:=\exp\left(\tfrac12\lambda_{{\boldsymbol{d}}}\lambda_{\boldsymbol{{\boldsymbol{d}}'}}\right)\frac1{s!}\prod_{i=1}^{n}d_i!\prod_{k=2}^{d_{\max}}(k!^{c_k}\cdot c_k!),$$ which is asymptotically uniform. The total number of such hypergraphs is thus $(1+O(\mathscr{E}+\rho_2+\rho_X))\mathscr{P}^{-1}$.

\label{theorem_dihy}
		Consider the iterative directed hypergraph process on $V$, ${\boldsymbol{d}}^{(1)}$, ${\boldsymbol{d}}^{(2)}$, ${\boldsymbol{d}}'^{(1)}$, ${\boldsymbol{d}}'^{(2)}$, and $X$. Let $$d_{\max}:=\max\{d_1^{(1)},\ldots,d_n^{(1)},d_1^{(2)},\ldots,d_n^{(2)},d_1'^{(1)},\ldots,d_m'^{(1)},d_1'^{(2)},\ldots,d_m'^{(2)}\},$$ and for $k^{(1)},k^{(2)}\geq1$, let $c_{k^{(1)},k^{(2)}}$ be the required number of hyperarcs of order $(k^{(1)},k^{(2)})$, and let $x_{k^{(1)},k^{(2)}}$ be the number of hyperarcs in $X$ of order $(k^{(1)},k^{(2)})$. Define
		\begin{align}
			\rho_{k^{(1)},k^{(2)}}&:=k^{(1)}!k^{(2)}!\binom{c_{k^{(1)},k^{(2)}}}{2}\left(\frac{\lambda_{{\boldsymbol{d}}^{(1)}}}{s^{(1)}}\right)^{k^{(1)}}\left(\frac{\lambda_{{\boldsymbol{d}}^{(2)}}}{s^{(2)}}\right)^{k^{(2)}}
			\\&\leq\binom{c_{k^{(1)},k^{(2)}}}{2}\left(\frac{k^{(1)}\lambda_{{\boldsymbol{d}}^{(1)}}}{s^{(1)}}\right)^{k^{(1)}}\left(\frac{k^{(2)}\lambda_{{\boldsymbol{d}}^{(2)}}}{s^{(2)}}\right)^{k^{(2)}},
			\\\rho_X&:=\sum_{(D,C)\in X}\frac{c_{|D|,|C|}|D|!|C|!}{(s^{(1)})^{|D|}(s^{(2)})^{|C|}}\prod_{v_{i^{(1)}}\in D}d_{i^{(1)}}^{(1)}\prod_{v_{i^{(2)}}\in C}d_{i^{(2)}}^{(2)}
			\\&\leq\sum_{k^{(1)}=1}^{d_{\max}}\sum_{k^{(2)}=1}^{d_{\max}}x_{k^{(1)},k^{(2)}}c_{k^{(1)},k^{(2)}}\left(\frac{k^{(1)}d_{\max}}{s^{(1)}}\right)^{k^{(1)}}\left(\frac{k^{(2)}d_{\max}}{s^{(2)}}\right)^{k^{(2)}}.
		\end{align}
		Assume that $s^{(1)}\leq s^{(2)}$ and consider the asymptotics as $s^{(1)}\to\infty$. Assume that $d_{\max}=O((s^{(1)})^{\sfrac14}/\log(s^{(1)}))$ and $\rho_{1,1},\rho_X=o(1)$. Then the total probability of rejection in the iterative edge-colored bipartite graph process is $O(d_{\max}^2/s^{(1)})$ in both iterations, and the probability of rejection afterwards is $O(\rho_{1,1}+\rho_{1,2}+\rho_{2,1}+\rho_X+1/s^{(1)})$. In particular, for $s^{(1)}$ large enough, there exists a simple directed hypergraph with out- and in degree sequences ${\boldsymbol{d}}^{(1)}$ and ${\boldsymbol{d}}^{(2)}$ and with hyperarcs not in $X$ and with orders $(d_1'^{(1)},d_1'^{(2)}),\ldots,(d_m'^{(1)},d_m'^{(2)})$. Furthermore, any such directed hypergraph is sampled with probability $(1+O(\mathscr{E}+\rho_{1,1}+\rho_X))\mathscr{P}$, where $\mathscr{E}:=\mathscr{E}(s^{(1)},d_{\max}^2)$ and
		\begin{align}
			\mathscr{P}&:=\exp\left(\tfrac12\lambda_{{\boldsymbol{d}}^{(1)}}\lambda_{{\boldsymbol{d}}'^{(1)}}+\tfrac12\lambda_{{\boldsymbol{d}}^{(2)}}\lambda_{{\boldsymbol{d}}'^{(2)}}+\lambda_{{\boldsymbol{d}}^{(1)},{\boldsymbol{d}}^{(2)}}\lambda_{{\boldsymbol{d}}'^{(1)},{\boldsymbol{d}}'^{(2)}}\right)
			\\&\quad\cdot\frac1{s^{(1)}!s^{(2)}!}\prod_{i=1}^{n}d_i^{(1)}!d_i^{(2)}!\prod_{k^{(1)}=1}^{d_{\max}}\prod_{k^{(2)}=1}^{d_{\max}}((k^{(1)}!k^{(2)}!)^{c_{k^{(1)},k^{(2)}}}(c_{k^{(1)},k^{(2)}})!),
		\end{align}
		which is asymptotically uniform. The total number of such directed hypergraphs is thus $(1+O(\mathscr{E}+\rho_{1,1}+\rho_X))\mathscr{P}^{-1}$.

For a graph $G=(V,E)$ with a set $F\subset V$ of forbidden vertices and an equivalence relation $R\subset V^2$ of forbidden pairs of vertices, we use the following notation for the equivalence class of a vertex $v$ or a set of vertices $U$:
	\begin{align}
		R(v)&:=\{w\in V:vRw\},
		\\R^*(v)&:=R(v)\setminus(\overline{N}(v)\cup F),
		\\R^*(U)&:=\cup_{u\in U}R^*(u).
	\end{align}

\label{definition_imfis}
		Consider a tuple $(G,F,R,{\bf{w}})$, where $G=(V,E)$ is a graph with $F\subset V$ a set of forbidden vertices, $R\subset V^2$ an equivalence relation of forbidden pairs of vertices, and ${\bf{w}}:V\to\mathbb{R}$ a weight function.

		Start with the empty set $\boldsymbol{S}_0=\emptyset$. For $r=0$ onward, if $(V\setminus\overline{N}(\boldsymbol{S}_r))\setminus(F\cup R^*(\boldsymbol{S}_r))$ is empty, let $\boldsymbol{S}_{r+1}=\boldsymbol{S}_r$. Otherwise, choose $v\in(V\setminus\overline{N}(\boldsymbol{S}_r))\setminus(F\cup R^*(\boldsymbol{S}_r))$ at random with probability proportional to $e^{-{\bf{w}}(v)}$, and let $\boldsymbol{S}_{r+1}=\boldsymbol{S}_r\cup\{v\}$. Finally, define $\boldsymbol{S}_{\infty}=\cup_{r=0}^{\infty}\boldsymbol{S}_r$.

\label{theorem_main}
		Assume that $\alpha\to\infty$, with $\ell$ fixed and $M=O(\alpha^{\sfrac12}/(\log\alpha)^2)$.
		\begin{enumerate}[(i)]
			\item\label{theorem_main_equation} Consider an FMIS $S$ of $G$. Define 
			\begin{align}
				\mathscr{P}(S)&:=\exp(P|F|+\tfrac12P|R^*(S)|+P{\bf{w}}(V)-{\bf{w}}(S))\prod_{t=1}^{\alpha}\frac{t}{n_t},\\
				\mathscr{E}(\alpha,M)&:=\frac{M^2\log\alpha}{\alpha}+\frac{M(\log\alpha)^2}{\alpha}.
			\end{align}
			Then the IMFIS process samples $S$ with probability
			\begin{align}
				\mathbb{P}(\boldsymbol{S}_{\infty}=S)&=(1+O(\mathscr{E}(\alpha,M)))\mathscr{P}(S).
			\end{align}
			\item\label{theorem_main_termination} The IMFIS process samples an FMIS with probability $$\mathbb{P}(|\boldsymbol{S}_{\infty}|=\alpha)=1-O(M/\alpha).$$ In particular, for $\alpha$ sufficiently large, this probability is positive, so $G$ has at least one FMIS.
		\end{enumerate}

\label{theorem_space}
		Let $T$ be an FIS of $G$ and let $V':=V\setminus\overline{N}(T)$, $\alpha':=\alpha-|T|$, and $P':=(\tfrac{\ell}{2}\alpha')^{-1}$. Let $U\subset V'\setminus(F\cup R^*(T))$ with $U_{\max}:=\max\{|\overline{N}(v)\cap U|:v\in V'\}$, and define $M':=\max\{M,U_{\max},\tfrac{\alpha}{\alpha'}R_{\max}^{(a)}\}$. Finally, define
		\begin{align}
			\mathscr{Q}(T,U)&:=\exp\Bigg(\tfrac12P'\sum_{v\in V'}\left(P|R^*(v)|-P'|R^*(v)\cap V'|\right)\Bigg.
			\\&\quad+P|F|-P'|F\cap V'|+P{\bf{w}}(V)-P'{\bf{w}}(V')
			\\&\quad\Bigg.+\tfrac12P|R^*(T)|-P'|R^*(T)\cap V'|-{\bf{w}}(T)-P'|U|\Bigg)\prod_{t=\alpha'+1}^{\alpha}\frac{t}{n_t}.
		\end{align}
		Assume that $\alpha'\to\infty$, with $\ell$ fixed and $M'=O((\alpha')^{\sfrac12}/(\log\alpha')^2)$. Then the IMFIS process samples an FMIS that contains the \emph{target set} $T$ and is disjoint from the \emph{exclusion set} $U$ with probability $$\mathbb{P}(|\boldsymbol{S}_{\infty}|=\alpha\wedge T\subset\boldsymbol{S}_{\infty}\wedge U\cap\boldsymbol{S}_{\infty}=\emptyset)=(1+O(\mathscr{E}(\alpha',M')))\mathscr{Q}(T,U).$$

\label{proposition_qt}
		Consider the quantity $\mathscr{Q}(T,U)$ from Theorem~\ref{theorem_space}.
		\begin{enumerate}[(i)]
			\item\label{proposition_qt_small} We have
			\begin{align}
				\mathscr{Q}(T,U)&=\left(\frac{2}{\ell}\right)^{|T|}\frac{(\alpha')!}{\alpha!}\exp\left(-P'|U|+O\left(\frac{|T|M'}{\alpha'}\right)\right)
				\\&=P^{|T|}\exp\left(-P|U|+O\left(\frac{|T|^2+|T|M'}{\alpha'}\right)\right).
			\end{align}
			\item\label{proposition_qt_uniform} If ${\bf{w}}(v)=\frac12P|R^*(v)|$ for all $v\in V$, then
			\begin{align}
				\mathscr{Q}(T,U)&=\exp\Bigg(P|F|-P'|F\cap V'|-P'|R^*(T)\cap V'|-P'|U|\Bigg.
				\\&\quad\Bigg.+\tfrac12P^2\sum_{v\in V}|R^*(v)|-\tfrac12(P')^2\sum_{v\in V'}|R^*(v)\cap V'|\Bigg)\prod_{t=\alpha'+1}^{\alpha}\frac{t}{n_t}.
			\end{align}
			Therefore, a uniformly random FMIS of $G$ contains $T$ and is disjoint from $U$ with probability $(1+O(\mathscr{E}(\alpha',M')))\mathscr{Q}(T,U)$.
		\end{enumerate}

Following the same reasoning as in Section~\ref{subsection_applications_colored}, this expression simplifies to
	\begin{align}
		\mathscr{P}(E^{(g)})&=\exp\Bigg(\tfrac12\lambda_{{\boldsymbol{d}}^{(g)}}\lambda_{{\boldsymbol{d}}'^{(g)}}+\sum_{h=g+1}^{\chi}\lambda_{{\boldsymbol{d}}^{(g)},{\boldsymbol{d}}^{(h)}}\lambda_{{\boldsymbol{d}}'^{(g)},{\boldsymbol{d}}'^{(h)}}+\mu_{{\boldsymbol{d}}^{(g)},{\boldsymbol{d}}'^{(g)}}^{X^{(g)}}\Bigg.
		\\&\quad+\sum_{h=1}^{g-1}\sum_{(v_i,v_j')\in E^{(h)}\setminus X^{(g)}}\frac{d_i^{(g)}d_j'^{(g)}}{m^{(g)}}-\sum_{h=g+1}^{\chi}\sum_{(v_i,v_j')\in E^{(g)}\setminus X^{(h)}}\frac{d_i^{(h)}d_j'^{(h)}}{m^{(h)}}
		\\&\quad\Bigg.+O\Bigg(\sum_{h=g}^{\chi}\frac{x_{\max}^{(h)}d_{\max}^{(g)}(d_{\max}^{(h)})^2}{m^{(h)}}+\sum_{h=1}^{g-1}\frac{d_{\max}^{(h)}(d_{\max}^{(g)})^3}{m^{(g)}}\Bigg)\Bigg)\frac1{m^{(g)}!}.
	\end{align}
	Finally, following the same reasoning as in Section~\ref{subsection_applications_colored} again, the result follows.\hfill$\square$

It follows that the expected number of pairs of vertices in $V'$ with identical neighborhoods inducing the same hyperedge of cardinality $k$ is
	\begin{align}
		&(1+O(\mathscr{E}))\binom{c_k}{2}\frac{k!^2}{s^{2k}}\sum_{1\leq i_1<\ldots<i_k\leq n}\prod_{l=1}^{k}d_{i_l}(d_{i_l}-1)
		\\&\leq(1+O(\mathscr{E}))\binom{c_k}{2}\frac{k!^2}{s^{2k}}\cdot\frac1{k!}\left(\sum_{i=1}^{n}d_{i}(d_{i}-1)\right)^k
		\\&\leq(1+O(\mathscr{E}))\rho_k.
	\end{align}

We need to calculate
\begin{equation}\label{eq:sum_S_inf=s}
	\mathbb{P}(|\boldsymbol{S}_{\infty}|=\alpha\wedge T\subset\boldsymbol{S}_{\infty}\wedge U\cap\boldsymbol{S}_{\infty}=\emptyset)=\sum_{S\in\mathcal{G}(T,U)}\mathbb{P}(\boldsymbol{S}_{\infty}=S),
\end{equation}
where $\mathcal{G}(T,U)$ is the set of all FMISs of $G$ that contain the target set $T$ and are disjoint from the exclusion set $U$.

We now consider the induced subgraph $G'$ of $G$ on the set $V'$ of vertices that are compatible with $T$ in an independent set. First, we rewrite equation \eqref{eq:sum_S_inf=s} as
\begin{equation}\label{eq:sum_S_inf=t_s}
	\mathbb{P}(|\boldsymbol{S}_{\infty}|=\alpha\wedge T\subset\boldsymbol{S}_{\infty}\wedge U\cap\boldsymbol{S}_{\infty}=\emptyset)=\sum_{S'\in\mathcal{G}'(T,U)}\mathbb{P}(\boldsymbol{S}_{\infty}=T\cup S'),
\end{equation}
where $\mathcal{G}'(T,U)$ is the set of all $S'\subset V'\setminus U$ for which $T\cup S'$ is an FMIS of $G$. Let furthermore $R'$ be $R$ restricted to $V'$, and let $F':=(F\cap V')\cup(R^*(T)\cap V')\cup U$. Then $\mathcal{G}'(T,U)$ is the set of all FMISs of $G'$ with respect to $F'$ and $R'$.

Now, we choose a modified weight function ${\bf{w}}':V'\to\mathbb{R}$, $${\bf{w}}'(v):={\bf{w}}(v)+\tfrac12P'|(R')^*(v)|-\tfrac12P|R^*(v)|$$ on $G'$ in such a way that the IMFIS process on $(G',F',R',{\bf{w}}')$ behaves like the original IMFIS process conditioned on containing $T$. We write $\boldsymbol{S}_{\infty}'$ to distinguish this IMFIS process from the one on $(G,F,R,{\bf{w}})$.

The main idea is to apply Theorem~\ref{theorem_main} to the IMFIS process on $(G',F',R',{\bf{w}}')$. Supposing the assumptions are met, by Theorem~\ref{theorem_main}~(\ref{theorem_main_termination}), we have $$\mathbb{P}(|\boldsymbol{S}_{\infty}'| = \alpha') = 1-O(M'/\alpha').$$ This can be rewritten as $$\sum_{S'\in\mathcal{G}'(T,U)}\mathbb{P}(\boldsymbol{S}_{\infty}=T\cup S')\frac{\mathbb{P}(\boldsymbol{S}_{\infty}'=S')}{\mathbb{P}(\boldsymbol{S}_{\infty}=T\cup S')} = 1-O(M'/\alpha').$$ The result then follows from \eqref{eq:sum_S_inf=t_s} if we show that Theorem~\ref{theorem_main}~(\ref{theorem_main_equation}) gives
\begin{equation}\label{eq:partial_asymptotic_prob}
	\frac{\mathbb{P}(\boldsymbol{S}_{\infty}'=S')}{\mathbb{P}(\boldsymbol{S}_{\infty}=T\cup S')}=(1+O(\mathscr{E}(\alpha',M')))\mathscr{Q}(T,U)^{-1}
\end{equation}
for any $S'\in\mathcal{G}'(T,U)$. In what follows, we thus verify the assumptions of Theorem~\ref{theorem_main} and we derive \eqref{eq:partial_asymptotic_prob}.

First, by Proposition~\ref{proposition_hereditary}, $G'$ is indeed $2$-uniform with $\alpha(G')=\alpha'\to\infty$, and with $\ell(G')=\ell$ fixed. Next, note that $(R')_{\max}^{(a)}\leq R_{\max}^{(a)}\leq M'$, $(R')_{\max}^{(b)}\leq R_{\max}^{(b)}\leq M'$, and $((R')_{\max}^{(c)})^2\leq(R_{\max}^{(c)})^2\leq M'$. For any $v\in V'$, we have $$|\overline{N}_{G'}(v)\cap F'|\leq|\overline{N}_G(v)\cap F|+|\overline{N}_G(v)\cap R^*(T)|+|\overline{N}_G(v)\cap U|,$$ so $F'_{\max}\leq F_{\max}+R_{\max}^{(b)}+U_{\max}\leq3M'$. Finally, we have $${\bf{w}}'_{\max}\alpha\leq {\bf{w}}_{\max}\alpha+\tfrac12P'\alpha(R')_{\max}^{(a)}+\tfrac12P\alpha R_{\max}^{(a)}\leq2M',$$ since $\ell\geq2$ gives $P\leq\alpha^{-1}$ and $P'\leq(\alpha')^{-1}$. We conclude that $$\max\{F'_{\max},(R')_{\max}^{(a)},(R')_{\max}^{(b)},((R')_{\max}^{(c)})^2,{\bf{w}}'_{\max}\alpha,1\}\leq3M'.$$

We may thus apply Theorem~\ref{theorem_main} to the IMFIS process on $(G',F',R',{\bf{w}}')$. It remains to derive \eqref{eq:partial_asymptotic_prob} by evaluating
\begin{align}
	&\frac{\mathbb{P}(\boldsymbol{S}_{\infty}'=S')}{\mathbb{P}(\boldsymbol{S}_{\infty}=T\cup S')}=\frac{(1+O(\mathscr{E}(\alpha',M')))\mathscr{P}'(S')}{(1+O(\mathscr{E}(\alpha,M)))\mathscr{P}(T\cup S')}
\end{align} 
for $S'\in\mathcal{G}'(T,U)$, where
\begin{align}
	&\mathscr{P}'(S')=\exp(P'|F'|+\tfrac12P'|(R')^*(S')|+P'{\bf{w}}'(V')-{\bf{w}}'(S'))\prod_{t=1}^{\alpha'}\frac{t}{n_t},
	\\&\mathscr{P}(T\cup S')=\exp(P|F|+\tfrac12P|R^*(T\cup S')|+P{\bf{w}}(V)-{\bf{w}}(T\cup S'))\prod_{t=1}^{\alpha}\frac{t}{n_t},
\end{align}
Comparing to \eqref{eq:partial_asymptotic_prob}, it suffices to show $\mathscr{P}(T\cup S')/\mathscr{P}'(S')=\mathscr{Q}(T,U)$. We have
\begin{align}
	\frac{\mathscr{P}(T\cup S')}{\mathscr{P}'(S')}&=\exp\bigg(\tfrac12P|R^*(S')|-\tfrac12P'|(R')^*(S')|-{\bf{w}}(S')+{\bf{w}}'(S')\bigg.
	\\&\quad+P|F|-P'|F'|+P{\bf{w}}(V)-P'{\bf{w}}'(V')
	\\&\quad\bigg.+\tfrac12P|R^*(T)|-{\bf{w}}(T)\bigg)\prod_{t=\alpha'+1}^{\alpha}\frac{t}{n_t}.
\end{align}
Here, all terms in the exponent that depend on $S'$ are grouped in the first line, and by definition of ${\bf{w}}'$, they sum to zero, since $S'$ is feasible. Since $|F'|=|F\cap V'|+|R^*(T)\cap V'|+|U|$, it remains to evaluate $$P'{\bf{w}}'(V')=P'{\bf{w}}(V')+\tfrac12P'\sum_{v\in V'}(P'|(R')^*(v)|-P|R^*(v)|).$$ The result follows, since $(R')^*(v)=R^*(v)\cap V'$ for $v\in V'$.

