\label{lemma_depth}
		Let $0<\delta<1$ with $\delta=o(1)$ and $\tfrac1{\delta}=o(\log\alpha)$. Let $0\leq\widetilde{k}\leq k-1$ and $\widetilde{K}\leq n_{\tilde{k}}$ with $K\leq n_k-\delta(n_k-\widetilde{K})$. Consider the event $$\widetilde{\mathcal{P}}^{\delta}:=\{n_{\alpha-r}-\Psi_r\geq\delta(n_{\alpha-r}-\widetilde{K}),\ \forall r=0,\ldots,\alpha-k-1\}\subset\mathcal{P}.$$ Then for $C=O(1)$, we have
		\begin{align}
			&\mathbb{E}\left(1_{\widetilde{\mathcal{P}}^{\delta}}\exp\left(C\sum_{r=0}^{\alpha-k-1}\frac{(K-\widetilde{K})^+}{n_{\alpha-r}-\Psi_r}\right)\right)
			\\&\leq\exp\left((\tfrac{C}{2}+o(1))k\log\log\alpha+O(\tfrac{1}{\delta}\widetilde{k})\right).
		\end{align}

By Lemma~\ref{lemma_bounds1}~(\ref{lemma_bounds1_v0}), substituting $i=\alpha-k-r$ gives $$\widetilde{\Sigma}^{(1)}:=\sum_{r=0}^{\alpha-k-1}\frac{(K-\widetilde{K})^+}{n_{\alpha-r}-n_k+\delta(n_k-\widetilde{K})}\leq\sum_{i=1}^{\alpha}\frac{(n_k-\widetilde{K})^+}{n_{k+i}-n_k+\delta(n_k-\widetilde{K})}.$$ Note that $\widetilde{K}\leq n_{\tilde{k}}<n_k$, so each term is at most $\tfrac1{\delta}$, which gives
\begin{align}
	\widetilde{\Sigma}^{(1)}
	&\leq\tfrac1{\delta}\widetilde{k}+\sum_{i=\tilde{k}+1}^{\alpha}\frac{n_k}{n_{k+i}-n_k+\delta(n_k-\widetilde{K})}
	\\&\leq\tfrac1{\delta}\widetilde{k}+n_k\sum_{i=\tilde{k}+1}^{\alpha}\frac{1}{n_{k+i}-n_k+\delta(n_k-n_{\tilde{k}})}.
\end{align}
By Lemma~\ref{lemma_nr}~(\ref{lemma_nr_sum}), we get
\begin{align}
	\widetilde{\Sigma}^{(2)}
	&:=\sum_{i=\tilde{k}+1}^{\alpha}\frac{1}{n_{k+i}-n_k+\delta(n_k-n_{\tilde{k}})}
	\\&=\sum_{i=\tilde{k}+1}^{\alpha}\frac{1}{n_i+\ell ki+\delta(n_k-n_{\tilde{k}})}
	\\&=\sum_{i=\tilde{k}+1}^{\alpha}\frac{1}{ai^2+bi+c}
\end{align}
for $a:=\tfrac{\ell}{2}$, $b:=\ell k+1-\tfrac{\ell}{2}$, and $c:=\delta(n_k-n_{\tilde{k}})$. Note that $a,b,c>0$, since $k\geq\widetilde{k}+1\geq1$. By Lemma~\ref{lemma_nr}~(\ref{lemma_nr_leq}), we find that $c\leq\delta k^2=o(b^2)$, so $D:=b^2-4ac=(1+o(1))b^2$ is also positive for $\alpha$ large enough.

For $\xi^{\pm}:=\tfrac1{2a}(b\pm\sqrt{D})$, we have $ai^2+bi+c=a(i+\xi^-)(i+\xi^+)$, which gives $$\widetilde{\Sigma}^{(2)}=\sum_{i=\tilde{k}+1}^{\alpha}\frac1{\sqrt{D}}\left(\frac1{i+\xi^-}-\frac1{i+\xi^+}\right).$$ We use the bounds
\begin{align}
	\sum_{i=\tilde{k}+1}^{\alpha}\frac1{i+\xi^-}
	&\leq\int_{\tilde{k}+\xi^-}^{\alpha+\xi^-}\frac1x\,\mathrm{d}x=\log\left(\frac{\alpha+\xi^-}{\tilde{k}+\xi^-}\right),
	\\\sum_{i=\tilde{k}+1}^{\alpha}\frac1{i+\xi^+}
	&\geq\int_{\tilde{k}+\xi^++1}^{\alpha+\xi^++1}\frac1x\,\mathrm{d}x=\log\left(\frac{\alpha+\xi^++1}{\tilde{k}+\xi^++1}\right),
	\\\widetilde{\Sigma}^{(2)}&\leq\frac1{\sqrt{D}}\log\left(\frac{\tilde{k}+\xi^++1}{\tilde{k}+\xi^-}\right),
\end{align}
where the last inequality uses $\alpha+\xi^-\leq\alpha+\xi^++1$.

Note that $D=b^2(1-\tfrac{4ac}{b^2})\leq b^2(1-\tfrac{2ac}{b^2})^2\leq b^2$, so $\xi^+\leq\tfrac{b}{a}$ and $\xi^-\geq\tfrac{c}{b}$. If $\widetilde{k}\leq k/\log\alpha$, such that $c=\Omega(\delta k^2)$ and $b(b+a)=O(k^2)$, we thus get $$\tfrac{\xi^++1}{\xi^-}\leq\tfrac{b(b+a)}{ac}=O(\tfrac{1}{\delta})=O(\log\alpha).$$ Otherwise, if $\widetilde{k}\geq k/\log\alpha$, we get $$\tfrac{\xi^++1}{\tilde{k}}\leq\tfrac{b+a}{a\tilde{k}}=O(\tfrac{k}{\tilde{k}})=O(\log\alpha).$$ Either way, since $\sqrt{D}=(1+o(1))b$, we find that
\begin{align}
	\frac{\tilde{k}+\xi^++1}{\tilde{k}+\xi^-}
	&\leq1+\frac{\xi^++1}{\max\{\tilde{k},\xi^-\}}=O(\log\alpha),
	\\\widetilde{\Sigma}^{(2)}
	&\leq\tfrac1{\sqrt{D}}\log(O(\log\alpha))\leq(1+o(1))\tfrac1{b}\log\log\alpha,
	\\\widetilde{\Sigma}^{(1)}
	&\leq\tfrac1{\delta}\widetilde{k}+(1+o(1))\tfrac{n_k}{b}\log\log\alpha.
\end{align}
Since $n_k=(\tfrac{\ell}{2}k+1-\tfrac{\ell}2)k\leq\tfrac12bk$, the result follows.

Fix some $0<\tau<1$, and let $\delta':=\tfrac1{1+\tau}$. We use
\begin{align}
	\mathbb{E}(1_{\widetilde{\mathcal{P}}^{\delta}}e^{C\widetilde{\Sigma}})
	&\leq\mathbb{E}(1_{\widetilde{\mathcal{P}}^{\delta}\cap\mathcal{P}_1^{\delta'}}e^{C\widetilde{\Sigma}})+\sum_{t=1}^{T^{\delta'}-1}\mathbb{E}(1_{\widetilde{\mathcal{P}}^{\delta}\cap\mathcal{P}_{t+1}^{\delta'}\cap\mathcal{Q}_t^{\delta'}}e^{C\widetilde{\Sigma}}),
	\\\widetilde{\Sigma}
	&:=\sum_{r=0}^{\alpha-k-1}\frac{(K-\widetilde{K})^+}{n_{\alpha-r}-\Psi_r}.
\end{align}

For $t=1,\ldots,T^{\delta'}$, in $\widetilde{\mathcal{P}}^{\delta}\cap\mathcal{P}_t^{\delta'}$, we have $$\widetilde{\Sigma}\leq\tfrac1{\delta'}\sum_{r=0}^{\alpha-k-t}\frac{(K-\widetilde{K})^+}{n_{\alpha-r}-n_k+\delta(n_k-\widetilde{K})}+\tfrac1{\delta}\sum_{r=\alpha-k-t+1}^{\alpha-k-1}\frac{(K-\widetilde{K})^+}{n_{\alpha-r}-\widetilde{K}}.$$ Since $K\leq n_k\leq n_{\alpha-r}$ by Lemma~\ref{lemma_bounds1}~(\ref{lemma_bounds1_v0}), by Lemma~\ref{lemma_special}, we get
\begin{align}
	\widetilde{\Sigma}
	&\leq\tfrac1{\delta'}\left((\tfrac12+o(1))k\log\log\alpha+\tfrac1{\delta}\widetilde{k}\right)+\tfrac1{\delta}(t-1)
	\\&\leq(1+\tau)(\tfrac12+o(1))k\log\log\alpha+O(\tfrac1{\delta}\widetilde{k})+o((t-1)\log\alpha).
\end{align}
In particular, this gives $$\mathbb{E}(1_{\widetilde{\mathcal{P}}^{\delta}\cap\mathcal{P}_1^{\delta'}}e^{C\tilde{\Sigma}})\leq\exp\left((1+\tau)(\tfrac{C}{2}+o(1))k\log\log\alpha+O(\tfrac1{\delta}\widetilde{k})\right).$$

For $r=0,\ldots,\alpha-k-1$ with $t:=\alpha-k-r\leq T^{\delta'}-1$, in $\mathcal{Q}_t^{\delta'}$, we have $\Delta_r^{(2)}+\Delta_r^{(1)}\geq(1-(1+o(1))\delta')(n_t+\ell tk)$ by Lemma~\ref{lemma_boundpt}. It follows that either $\Delta_r^{(2)}\geq(1-(1+o(1))\delta')n_t$ or $\Delta_r^{(1)}\geq(1-(1+o(1))\delta')\ell tk$. By Lemma~\ref{lemma_pd}~(\ref{lemma_pd_2small},\ref{lemma_pd_1}), since $\delta'\leq1-\Omega(1)$, we get $$\mathbb{P}(\mathcal{Q}_t^{\delta'})\leq\exp(O(\log\alpha)-\Omega(t\log\alpha)).$$ It follows that
\begin{align}
	&\mathbb{E}(1_{\widetilde{\mathcal{P}}^{\delta}\cap\mathcal{P}_{t+1}^{\delta'}\cap\mathcal{Q}_t^{\delta'}}e^{C\tilde{\Sigma}})
	\\&\leq\exp\left((1+\tau)(\tfrac{C}{2}+o(1))k\log\log\alpha+O(\tfrac1{\delta}\widetilde{k}+\log\alpha)-\Omega(t\log\alpha)\right).
\end{align}
For $\alpha$ large enough, we thus have
\begin{align}
	&\mathbb{E}(1_{\widetilde{\mathcal{P}}^{\delta}\cap\mathcal{P}_{t+1}^{\delta'}\cap\mathcal{Q}_t^{\delta'}}e^{C\tilde{\Sigma}})
	\\&\leq\alpha^{C-\varepsilon t}\exp\left((1+\tau)(\tfrac{C}{2}+o(1))k\log\log\alpha+O(\tfrac1{\delta}\widetilde{k})\right)
\end{align}
for some fixed constants $C,\varepsilon>0$. For $t^*:=\lfloor\tfrac{C}{\varepsilon}\rfloor$, we get
\begin{align}
	&\sum_{t=t^*+1}^{T^{\delta'}-1}\mathbb{E}(1_{\widetilde{\mathcal{P}}^{\delta}\cap\mathcal{P}_{t+1}^{\delta'}\cap\mathcal{Q}_t^{\delta'}}e^{C\tilde{\Sigma}})
	\\&\leq(1+o(1))\exp\left((1+\tau)(\tfrac{C}{2}+o(1))k\log\log\alpha+O(\tfrac1{\delta}\widetilde{k})\right),
\end{align}
since $\sum_{i\geq n}x^i=(1+o(1))x^n$ for $x=o(1)$.

Finally, for $t\leq t^*=O(1)$, by Lemma~\ref{lemma_pd0}, we get $$\mathbb{P}(\mathcal{Q}_t^{\delta'})=O((k+1)M/\alpha)=o(1).$$ It follows that
\begin{align}
	&\mathbb{E}(1_{\widetilde{\mathcal{P}}^{\delta}\cap\mathcal{P}_{t+1}^{\delta'}\cap\mathcal{Q}_t^{\delta'}}e^{C\tilde{\Sigma}})
	\\&\leq\exp\left((1+\tau)(\tfrac{C}{2}+o(1))k\log\log\alpha+O(\tfrac1{\delta}\widetilde{k})\right),
	\\&\sum_{t=1}^{t^*}\mathbb{E}(1_{\widetilde{\mathcal{P}}^{\delta}\cap\mathcal{P}_{t+1}^{\delta'}\cap\mathcal{Q}_t^{\delta'}}e^{C\tilde{\Sigma}})
	\\&\leq\exp\left((1+\tau)(\tfrac{C}{2}+o(1))k\log\log\alpha+O(\tfrac1{\delta}\widetilde{k})\right).
\end{align}

Collecting results, we have $$\mathbb{E}(1_{\widetilde{\mathcal{P}}^{\delta}}e^{C\tilde{\Sigma}})\leq\exp\left((1+\tau)(\tfrac{C}{2}+o(1))k\log\log\alpha+O(\tfrac1{\delta}\widetilde{k})\right).$$ Since this holds for any $\tau>0$, the result follows.

\label{lemma_recycle}
		Let $0<\delta<1$ with $\delta=O(\tfrac{\log\log\alpha}{\log\alpha})$, and let $\mu_1,\mu_2>0$ with $\mu_2=\Omega(1)$, $\mu_1+\mu_2=1$, and
		\begin{equation}\label{equation_recycle}
			\delta\geq\tfrac1{\mu_1}\left(8\left(1-\tfrac{\log M}{\log\alpha}\right)+2+\Omega(1)\right)\tfrac{\log\log\alpha}{\log\alpha}.
		\end{equation}
		Let $r=0,\ldots,\alpha-k-1$ with $t:=\alpha-k-r=O(M)$. Then $$\mathbb{E}(\Pi_t1_{\mathcal{P}_t^{\delta}}|S_r)\leq\exp\left((\tfrac{1}{2\mu_2}+o(1))t\log\log\alpha+O(\tfrac1{\delta}k)\right).$$

Consider the FIS $S':=S_r$ of size $\alpha-k'$ with $k':=k+t=O(M)$, and let $K':=|(V\setminus\overline{N}(S'))\cap(F\cup R^*(S'))|=\Delta_r$. Since this fits the premise of Lemma~\ref{lemma_generalization}, we can follow the framework from Section~\ref{subsection_proof_framework} to reach the same conclusions.

Let $\mathcal{P}'$ be the set of all possible permutations $\pi'=(s_0',\ldots,s_{\alpha-k'-1}')$ of the elements of $S'$, and consider if $\pi'$ is a uniformly random permutation from $\mathcal{P}'$. For $r'=0,\ldots,\alpha-k'-1$, we get the random variable $S_{r'}':=S_{r'}'(\pi'):=\{s_0',\ldots,s_{r'-1}'\}$. We can define $\widetilde{V}_{r'}'$, $V_{r'}'$, and $\Psi_{r'}'$ again, as done in Section~\ref{subsection_proof_framework}.

Next, for $p\in[0,1]$, let $S_p'$ contain each element of $S'$ independently with probability $p$. Again, similarly define $\widetilde{V}_p'$, $V_p'$, and $\Psi_p'$, and define $\psi_p':=\mathbb{E}(\Psi_p')$. Furthermore, for $r'=0,\ldots,\alpha-k'-1$, define $p_{r'}':=r'/(\alpha-k')$, and write $q:=1-p$ and $q_{r'}':=1-p_{r'}'$.

We can apply any Lemma~of which the proof is already finished to this new context. Firstly, Lemma~\ref{lemma_expectation} gives $$\psi_p'=K'+q^2(|F|+p|R^*(S')|+{\bf{w}}(V))+O(qM^2+(n_{k'}-K')M/\alpha).$$ Secondly, using \eqref{equation_recycle}, Lemma~\ref{lemma_sigma}~(\ref{lemma_sigma_large}) gives $$\mathbb{E}\left(\exp\left(\tfrac{1}{\mu_1\delta}\sum_{r'=0}^{\alpha-k'-1}\frac{(\Psi_{r'}'-\psi_{p_{r'}'}')^+}{n_{\alpha-r'}-n_{k'}}\right)\right)\leq e^{o(k')}.$$ Thirdly, and finally, if $K'\leq n_{k'}-\delta(n_{k'}-K)$, then for $$\widetilde{\mathcal{P}}'^{\delta}:=\{n_{\alpha-r'}-\Psi_{r'}'\geq\delta(n_{\alpha-r'}-K),\ \forall r'=0,\ldots,\alpha-k'-1\},$$ Lemma~\ref{lemma_depth} gives
\begin{align}
	&\mathbb{E}\left(1_{\widetilde{\mathcal{P}}'^{\delta}}\exp\left(\tfrac1{\mu_2}\sum_{r'=0}^{\alpha-k'-1}\frac{(K'-K)^+}{n_{\alpha-r'}-\Psi_{r'}'}\right)\right)
	\\&\leq\exp\left((\tfrac{1}{2\mu_2}+o(1))k'\log\log\alpha+O(\tfrac1{\delta}k)\right).
\end{align}

The crucial observation is that the permutation $\overline{\pi}:=(s_0,\ldots,s_{\alpha-k'-1})$ is already a uniformly random permutation from $\mathcal{P}'$, if we condition on $S_r$. We may thus assume that $\pi'=\overline{\pi}$. For all $r'=0,\ldots,\alpha-k'-1$, this gives $S_{r'}'=S_{r'}$, and thus $\Psi_{r'}'=\Psi_{r'}$. We even get equality of the events $\mathcal{P}_{t+1}^{\delta}=\widetilde{\mathcal{P}}'^{\delta}$.

Reinterpreting the results, we find that Lemma~\ref{lemma_sigma}~(\ref{lemma_sigma_large}) now gives $$\mathbb{E}\Bigg(\exp\Bigg(\tfrac{1}{\mu_1\delta}\sum_{r'=0}^{\alpha-k'-1}\frac{(\Psi_{r'}-\psi_{p_{r'}'}')^+}{n_{\alpha-r'}-n_{k'}}\Bigg)\Bigg|S_r\Bigg)\leq e^{o(k+t)}.$$ Furthermore, in $\mathcal{P}_t^{\delta}$, for $r'=0,\ldots,\alpha-k'-1$ we have $$n_{\alpha-r'}-\Psi_{r'}\geq\delta(n_{\alpha-r'}-K)\geq\delta(n_{\alpha-r'}-n_k)\geq\delta(n_{\alpha-r'}-n_{k'})$$ by Lemma~\ref{lemma_bounds1}~(\ref{lemma_bounds1_v0}), so it follows that $$\mathbb{E}\Bigg(1_{\mathcal{P}_t^{\delta}}\exp\Bigg(\tfrac{1}{\mu_1}\sum_{r'=0}^{\alpha-k'-1}\frac{(\Psi_{r'}-\psi_{p_{r'}'}')^+}{n_{\alpha-r'}-\Psi_{r'}}\Bigg)\Bigg|S_r\Bigg)\leq e^{o(k+t)}.$$ Next, in $\mathcal{P}_t^{\delta}$, note that we have $n_{k'}-\Psi_r\geq\delta(n_{k'}-K)$, and thus $K'=\Delta_r\leq\Psi_r\leq n_{k'}-\delta(n_{k'}-K)$. Since $\mathcal{P}_t^{\delta}\subset\mathcal{P}_{t+1}^{\delta}=\widetilde{\mathcal{P}}'^{\delta}$, Lemma~\ref{lemma_depth} thus now gives
\begin{align}
	&\mathbb{E}\Bigg(1_{\mathcal{P}_t^{\delta}}\exp\Bigg(\tfrac1{\mu_2}\sum_{r'=0}^{\alpha-k'-1}\frac{(K'-K)^+}{n_{\alpha-r'}-\Psi_{r'}}\Bigg)\Bigg|S_r\Bigg)
	\\&\leq\exp\left((\tfrac{1}{2\mu_2}+o(1))(k+t)\log\log\alpha+O(\tfrac1{\delta}k)\right)
	\\&\leq\exp\left((\tfrac{1}{2\mu_2}+o(1))t\log\log\alpha+O(\tfrac1{\delta}k)\right),
\end{align}
since $\log\log\alpha=O(\tfrac{1}{\delta})$.

In order to bound $\mathbb{E}(\Pi_t1_{\mathcal{P}_t^{\delta}}|S_r)$ from this, we use
\begin{align}
	\log\Pi_t
	&\leq\sum_{r'=0}^{\alpha-k'-1}(\widetilde{Q}_{r'})^+=\sum_{r'=0}^{\alpha-k'-1}\frac{(\Psi_{r'}-\psi_{p_{r'}})^+}{n_{\alpha-r'}-\Psi_{r'}}
	\\&\leq\sum_{r'=0}^{\alpha-k'-1}\frac{(\Psi_{r'}-\psi_{p_{r'}'}')^++(\psi_{p_{r'}'}'-\psi_{p_{r'}}+K-K')^++(K'-K)^+}{n_{\alpha-r'}-\Psi_{r'}}.
\end{align}
For $r'=0,\ldots,\alpha-k'-1$, we use Lemma~\ref{lemma_expectation} to bound
\begin{align}
	&(\psi_{p_{r'}'}'-\psi_{p_{r'}}+K-K')^+
	\\&\leq|q_{r'}'^2-q_{r'}^2|(|F|+{\bf{w}}(V))+|q_{r'}'^2p_{r'}'|R^*(S_r)|-q_{r'}^2p_{r'}|R^*(S)||
	\\&+O((q_{r'}'+q_{r'})M^2+(n_k-K+n_{k'}-K')M/\alpha).
\end{align}
Note that $k\leq k'$ gives $n_k-K+n_{k'}-K'\leq2n_{k'}\leq\ell k'^2$ by Lemma~\ref{lemma_nr}~(\ref{lemma_nr_leq}). We furthermore get $p_{r'}\leq p_{r'}'$, so $q_{r'}'\leq q_{r'}$, and thus $q_{r'}'+q_{r'}\leq2q_{r'}$. Next, we have
\begin{align}
	&|q_{r'}'^2p_{r'}'|R^*(S_r)|-q_{r'}^2p_{r'}|R^*(S)||
	\\&\leq p_{r'}'|q_{r'}'^2-q_{r'}^2||R^*(S)|+q_{r'}'^2p_{r'}'|R^*(S\setminus S_r)|+q_{r'}^2|p_{r'}'-p_{r'}||R^*(S)|
	\\&\leq|q_{r'}'^2-q_{r'}^2||R^*(S)|+q_{r'}|R^*(S\setminus S_r)|+q_{r'}|p_{r'}'-p_{r'}||R^*(S)|,
\end{align}
so we need to bound
\begin{align}
	q_{r'}^2-q_{r'}'^2
	&=\tfrac{(\alpha-k-r')^2}{(\alpha-k)^2}-\tfrac{(\alpha-k'-r')^2}{(\alpha-k')^2}
	\\&=\tfrac{(\alpha-k-r')^2(\alpha-k')^2-(\alpha-k'-r')^2(\alpha-k)^2}{(\alpha-k)^2(\alpha-k')^2}
	\\&=\tfrac{2r't(\alpha-k)(\alpha-k'-r')+r'^2t^2}{(\alpha-k)^2(\alpha-k')^2}=O(q_{r'}'M/\alpha+t^2/\alpha^2),
	\\p_{r'}'-p_{r'}
	&=\tfrac{r't}{(\alpha-k')(\alpha-k)}=O(M/\alpha).
\end{align}
We further use Lemma~\ref{lemma_terms} to conclude $$(\psi_{p_{r'}'}'-\psi_{p_{r'}}+K-K')^+=O(q_{r'}M^2+k'^2M/\alpha).$$ In $\mathcal{P}_t^{\delta}$, by Lemma~\ref{lemma_sums}~(\ref{lemma_sums_3},\ref{lemma_sums_4}), we thus get
\begin{align}
	&\sum_{r'=0}^{\alpha-k'-1}\frac{(\psi_{p_{r'}'}'-\psi_{p_{r'}}+K-K')^+}{n_{\alpha-r'}-\Psi_{r'}}
	\\&=O\left(\tfrac{1}{\delta}\sum_{r'=0}^{\alpha-k-1}\frac{q_{r'}M^2}{n_{\alpha-r'}-n_k}+\tfrac{1}{\delta}\sum_{r'=0}^{\alpha-k'-1}\frac{k'^2M/\alpha}{n_{\alpha-r'}-n_{k'}}\right)
	\\&=O(\tfrac{1}{\delta}M^2\log\alpha/\alpha)=o(1).
\end{align}

By convexity of the exponential function, we get
\begin{align}
	&\mathbb{E}(\Pi_t1_{\mathcal{P}_t^{\delta}}|S_r)
	\\&\leq\mathbb{E}\Bigg(1_{\mathcal{P}_t^{\delta}}\exp\Bigg(\sum_{r'=0}^{\alpha-k'-1}\frac{(\Psi_{r'}-\psi_{p_{r'}'}')^++(K'-K)^+}{n_{\alpha-r'}-\Psi_{r'}}+o(1)\Bigg)\Bigg|S_r\Bigg)
	\\&\leq\mu_1e^{o(1)}\mathbb{E}\Bigg(1_{\mathcal{P}_t^{\delta}}\exp\Bigg(\tfrac1{\mu_1}\sum_{r'=0}^{\alpha-k'-1}\frac{(\Psi_{r'}-\psi_{p_{r'}'}')^+}{n_{\alpha-r'}-\Psi_{r'}}\Bigg)\Bigg|S_r\Bigg)
	\\&+\mu_2e^{o(1)}\mathbb{E}\Bigg(1_{\mathcal{P}_t^{\delta}}\exp\Bigg(\tfrac1{\mu_2}\sum_{r'=0}^{\alpha-k'-1}\frac{(K'-K)^+}{n_{\alpha-r'}-\Psi_{r'}}\Bigg)\Bigg|S_r\Bigg).
\end{align}
The result follows, because $\mu_1+\mu_2=1$.

For $r'=\alpha-k-t,\ldots,\alpha-k-1$ with $t':=\alpha-k-r'\leq t$, by Lemma~\ref{lemma_expectation} and Lemma~\ref{lemma_nr}~(\ref{lemma_nr_sum},\ref{lemma_nr_leq}), we have
\begin{align}
	n_{\alpha-r'}-\psi_{p_{r'}}
	&=n_{t'+k}-n_k+n_k-K+O(q_{r'}^2\alpha M+q_{r'}M^2+(n_k-K)M/\alpha)
	\\&\leq\tfrac{\ell}{2}t'^2+\ell t'k+O(t'^2M/\alpha+t'M^2/\alpha+(n_k-K))
	\\&=O(t'(k+t)+(n_k-K)).
\end{align}
Furthermore, for $\alpha$ large enough, such that ${\bf{w}}_{\max}\leq\tfrac12$, we have $$n_{\alpha-r'}-\Psi_{r'}=\sum_{v\in V_{r'}}(1-{\bf{w}}(v))\geq\tfrac12|V_{r'}|.$$ Since $|V_{r'}|\geq|S\setminus S_{r'}|+|V^{(0)}\setminus (F^{(0)}\cup R^{(0)})|=t'+(n_k-K)$, we get $$\frac{n_{\alpha-r'}-\psi_{p_{r'}}}{n_{\alpha-r'}-\Psi_{r'}}=O(k+t).$$ The result follows by expanding $\log(\Pi/\Pi_t)$.

By the law of total expectation, since $\mathcal{Q}_t^{\delta}$ is $S_r$-measurable, we have
\begin{align}
	\mathbb{E}(\Pi1_{\mathcal{P}_{t+1}^{\delta}\cap\mathcal{Q}_t^{\delta}})
	&=\mathbb{E}(\mathbb{E}(\Pi1_{\mathcal{P}_{t+1}^{\delta}\cap\mathcal{Q}_t^{\delta}}|S_r))
	\\&=\mathbb{E}(1_{\mathcal{Q}_t^{\delta}}\mathbb{E}(\Pi1_{\mathcal{P}_{t+1}^{\delta}}|S_r))
	\\&=\mathbb{E}(1_{\mathcal{Q}_t^{\delta}}\mathbb{E}(\mathbb{E}(\Pi1_{\mathcal{P}_{t+1}^{\delta}}|S_r,S_{r-1})|S_r)).
\end{align}
Let $r':=r-1$ and $t':=\alpha-k-r'=t+1$. By Lemma~\ref{lemma_pit}, we have $$\mathbb{E}(\Pi1_{\mathcal{P}_{t+1}^{\delta}}|S_r,S_{r-1})\leq\exp(t'\log(k+t')+O(t'))\mathbb{E}(\Pi_{t'}1_{\mathcal{P}_{t'}^{\delta}}|S_{r'+1},S_{r'}).$$ Conditioned on $S_{r'}$, we note that $\Pi_{t'}$ and $1_{\mathcal{P}_{t'}^{\delta}}$ are independent of $S_{r'+1}$, so by Lemma~\ref{lemma_recycle}, we get
\begin{align}
	&\mathbb{E}(\Pi_{t'}1_{\mathcal{P}_{t'}^{\delta}}|S_{r'+1},S_{r'})
	=\mathbb{E}(\Pi_{t'}1_{\mathcal{P}_{t'}^{\delta}}|S_{r'})
	\\&\leq\exp\left((\tfrac1{2\mu_2}+o(1))t'\log\log\alpha+O(\tfrac1{\delta}k)\right).
\end{align}
Combining results, since $t'=o(t'\log\log\alpha)$, we get
\begin{align}
	&\mathbb{E}(\Pi1_{\mathcal{P}_{t+1}^{\delta}\cap\mathcal{Q}_t^{\delta}})
	\\&\leq\exp\left(t'\log(k+t')+(\tfrac1{2\mu_2}+o(1))t'\log\log\alpha+O(\tfrac1{\delta}k)\right)\mathbb{E}(1_{\mathcal{Q}_t^{\delta}})
	\\&\leq\exp\left(t\log t+(\tfrac1{2\mu_2}+o(1))t\log\log\alpha+O(\tfrac1{\delta}k)\right)\mathbb{P}(\mathcal{Q}_t^{\delta}).
\end{align}
The second inequality uses $\log(k+t')\leq k+t'\leq O(\tfrac1{\delta}k)+o(t'\log\log\alpha)$ and $t\log(\tfrac{k+t'}{t})\leq k+1\leq O(\tfrac1{\delta}k)+o(t'\log\log\alpha)$.

We use $$\mathbb{E}(\Pi1_{\mathcal{P}\setminus\mathcal{P}^{\delta}})\leq\sum_{t=1}^{T^{\delta}-1}\mathbb{E}(\Pi1_{\mathcal{P}_{t+1}^{\delta}\cap\mathcal{Q}_t^{\delta}}).$$ Consider some $t=1,\ldots,T^{\delta}-1$ with $r:=\alpha-k-t$. By Lemma~\ref{lemma_boundpt}, in $\mathcal{Q}_t^{\delta}$, we have $\Delta_r^{(2)}+\Delta_r^{(1)}\geq(1-(1+o(1))\delta)(n_t+\ell tk)$. It follows that either $\Delta_r^{(2)}\geq(1-(1+o(1))\delta)n_t$ or $\Delta_r^{(1)}\geq(1-(1+o(1))\delta)\ell tk$.

For $t\leq\log\alpha$, by Lemma~\ref{lemma_pd}~(\ref{lemma_pd_2small},\ref{lemma_pd_1}), we get $$\mathbb{P}(\mathcal{Q}_t^{\delta})\leq\exp\left(O(\log\alpha)-\Omega(t\log\alpha)\right).$$ By Lemma~\ref{lemma_pipt}, this gives $$\mathbb{E}(\Pi1_{\mathcal{P}_{t+1}^{\delta}\cap\mathcal{Q}_t^{\delta}})\leq\exp\left(O(\tfrac1{\delta}k+\log\alpha)-\Omega(t\log\alpha)\right).$$ For $\alpha$ large enough, we thus have $$\mathbb{E}(\Pi1_{\mathcal{P}_{t+1}^{\delta}\cap\mathcal{Q}_t^{\delta}})\leq\alpha^{C-\varepsilon t}e^{O(\frac1{\delta}k)}$$ for some fixed constants $C,\varepsilon>0$.

First, let $t^{(1)}:=\lfloor\tfrac{C+1}{\varepsilon}\rfloor$ and $t^{(2)}:=\lfloor\log\alpha\rfloor$, and assume that $\alpha$ is large enough, such that $t^{(1)}<t^{(2)}$. We get $$\sum_{t=t^{(1)}+1}^{t^{(2)}}\mathbb{E}(\Pi1_{\mathcal{P}_{t+1}^{\delta}\cap\mathcal{Q}_t^{\delta}})\leq(1+o(1))\alpha^{C-\varepsilon(t^{(1)}+1)}e^{O(\frac1{\delta}k)}\leq\tfrac{1}{\alpha}e^{O(\frac1{\delta}k)},$$ since $\sum_{i\geq n}x^i=(1+o(1))x^n$ for $x=o(1)$, and $C-\varepsilon(t^{(1)}+1)<-1$.

Second, consider $1\leq t\leq t^{(1)}=O(1)$. Note that $\Delta_r^{(2)}\leq|\widetilde{V}_r\cap V^{(2)}|=|\widetilde{V}_r\setminus S|=n_t-t$. In $\mathcal{Q}_t^{\delta}$, we get
\begin{align}
	\Delta_r^{(1)}
	&\geq(1-(1+o(1))\delta)(n_t+\ell tk)-\Delta_r^{(2)}
	\\&\geq(1-(1+o(1))\delta)\ell tk+t-(1+o(1))\delta n_t
	\\&\geq(1-(1+o(1))\delta)\ell tk,
\end{align}
for $\alpha$ large enough, since $(1+o(1))\delta n_t=o(1)$. By Lemma~\ref{lemma_pd0}~(\ref{lemma_pd0_d1}), we get $$\mathbb{P}(\mathcal{Q}_t^{\delta})=O(kM/\alpha).$$ By Lemma~\ref{lemma_pipt}, and using case analysis on $k=0$ and $k\geq1$, this gives $$\mathbb{E}(\Pi1_{\mathcal{P}_{t+1}^{\delta}\cap\mathcal{Q}_t^{\delta}})\leq\tfrac{kM}{\alpha}\exp\left(O(\tfrac1{\delta}k+\log\log\alpha)\right)\leq\tfrac{M}{\alpha}e^{O(\frac1{\delta}k)}.$$ Indeed, if $k=0$, then the expectation evaluates to $0$, and otherwise, we have $\log k\leq k=O(\tfrac1{\delta}k)$ and $\log\log\alpha=O(\tfrac1{\delta}k)$, since $k\geq1$. It follows that $$\sum_{t=1}^{t^{(1)}}\mathbb{E}(\Pi1_{\mathcal{P}_{t+1}^{\delta}\cap\mathcal{Q}_t^{\delta}})\leq\tfrac{M}{\alpha}e^{O(\frac1{\delta}k)}.$$

Third, let $t^{(3)}:=\min\{\lfloor k(\log\alpha)^{\sfrac12}\rfloor,T^{\delta}-1\}$, and consider if $t^{(2)}<t^{(3)}$. Note that we get $k=\Omega((\log\alpha)^{\sfrac12})$, such that $\log\alpha=O(\tfrac1{\delta}k)$. For $t=t^{(2)}+1,\ldots,t^{(3)}$, we furthermore have $t\log\log\alpha=O(\tfrac1{\delta}k)$.

By Lemma~\ref{lemma_pd}~(\ref{lemma_pd_2small},\ref{lemma_pd_1}), we get $$\mathbb{P}(\mathcal{Q}_t^{\delta})\leq\exp\left(t\log\tfrac{M}{\alpha}+O(\tfrac1{\delta}k)\right).$$ By Lemma~\ref{lemma_pipt}, this gives
\begin{align}
	\mathbb{E}(\Pi1_{\mathcal{P}_{t+1}^{\delta}\cap\mathcal{Q}_t^{\delta}})
	&\leq\exp\left(t\log\tfrac{tM}{\alpha}+O(\tfrac1{\delta}k)\right)\leq(\tfrac{T^{\delta}M}{\alpha})^te^{O(\frac1{\delta}k)},
	\\\sum_{t=t^{(2)}+1}^{t^{(3)}}\mathbb{E}(\Pi1_{\mathcal{P}_{t+1}^{\delta}\cap\mathcal{Q}_t^{\delta}})
	&\leq(1+o(1))(\tfrac{T^{\delta}M}{\alpha})^{t^{(2)}}e^{O(\frac1{\delta}k)}\leq\tfrac{1}{\alpha}e^{O(\frac1{\delta}k)},
\end{align}
because $T^{\delta}M/\alpha=O(M^2/\alpha)=o(1)$ by Lemma~\ref{lemma_t}.

Fourth and finally, we consider $t=\max\{t^{(2)},t^{(3)}\}+1,\ldots,T^{\delta}-1$, such that $\delta t\to\infty$ and $k=o(t)$. Note that Lemma~\ref{lemma_fs}~(\ref{lemma_fs_one}) gives $\Delta_r^{(1)}\leq\ell tk$. In $\mathcal{Q}_t^{\delta}$, we get
\begin{align}
	\Delta_r^{(2)}
	&\geq(1-(1+o(1))\delta)(n_t+\ell tk)-\Delta_r^{(1)}
	\\&\geq(1-(1+o(1))\delta)n_t-(1+o(1))\delta\ell tk
	\\&=(1-(1+o(1))\delta)n_t,
\end{align}
since $(1+o(1))\delta\ell tk=o(\delta t^2)=o(\delta n_t)$ by Lemma~\ref{lemma_nr}~(\ref{lemma_nr_geq}). By Lemma~\ref{lemma_pd}~(\ref{lemma_pd_2large}), we get $$\mathbb{P}(\mathcal{Q}_t^{\delta})\leq\exp\left((1-(\tfrac12+o(1))\delta)t\log\tfrac{M}{\alpha}+O(t)\right).$$ By Lemma~\ref{lemma_pipt}, this gives
\begin{align}
	&\mathbb{E}(\Pi1_{\mathcal{P}_{t+1}^{\delta}\cap\mathcal{Q}_t^{\delta}})
	\\&\leq\exp\left(t\left(\log\tfrac{tM}{\alpha}+\tfrac1{2\mu_2}\log\log\alpha-\tfrac12\delta\log\tfrac{M}{\alpha}+o(\log\log\alpha)\right)+O(t+\tfrac1{\delta}k)\right)
	\\&\leq\exp\left(O(\tfrac1{\delta}k)-\Omega(t\log\log\alpha)\right),
\end{align}
where the second inequality uses
\begin{align}
	-\tfrac12\delta\log\tfrac{M}{\alpha}
	&=\tfrac12\log\alpha\cdot\delta\left(1-\tfrac{\log M}{\log\alpha}\right)
	\\&\leq\log\alpha\left(2\left(\tfrac12-\tfrac{\log M}{\log\alpha}\right)-(\tfrac1{2\mu_2}+\Omega(1))\tfrac{\log\log\alpha}{\log\alpha}\right)
	\\&=-\log\tfrac{M^2}{\alpha}-\tfrac1{2\mu_2}\log\log\alpha-\Omega(\log\log\alpha).
\end{align}
For $\alpha$ large enough, we thus have $$\mathbb{E}(\Pi1_{\mathcal{P}_{t+1}^{\delta}\cap\mathcal{Q}_t^{\delta}})\leq(\log\alpha)^{-\varepsilon't}e^{O(\frac1{\delta}k)}$$ for some fixed constant $\varepsilon'>0$. We get
\begin{align}
	\sum_{t=\max\{t^{(2)},t^{(3)}\}+1}^{T^{\delta}-1}\mathbb{E}(\Pi1_{\mathcal{P}_{t+1}^{\delta}\cap\mathcal{Q}_t^{\delta}})
	&\leq(1+o(1))(\log\alpha)^{-\varepsilon'(t^{(2)}+1)}e^{O(\frac1{\delta}k)}
	\\&\leq\exp\left(O(\tfrac1{\delta}k)-\Omega(\log\alpha\log\log\alpha)\right)
	\\&\leq\exp\left(O(\tfrac1{\delta}k)-\log\alpha\right)
\end{align}
for $\alpha$ large enough. The result follows.

\label{lemma_stuck}
		Let $k\geq1$ be an integer.
		\begin{enumerate}[(i)]
			\item\label{lemma_stuck_small} If $k=O(1)$, then $\mathbb{P}(|\boldsymbol{S}_{\infty}|=\alpha-k)=O((M/\alpha)^k)$.
			\item\label{lemma_stuck_large} If $k=O(M)$, then $\mathbb{P}(|\boldsymbol{S}_{\infty}|=\alpha-k)\leq\alpha^{o(k)}(M/\alpha)^k$.
		\end{enumerate}

\label{lemma_ratio}
		Let $k\geq1$ be an integer. Consider related sets $S\in\mathcal{G}$ and $\widetilde{S}\in\mathcal{G}_k$.
		\begin{enumerate}[(i)]
			\item\label{lemma_ratio_small} If $k=O(1)$, then $\mathbb{P}(\boldsymbol{S}_{\infty}=\widetilde{S})/\mathbb{P}(\boldsymbol{S}_{\infty}=S)=O((k^2/\alpha)^k)$.
			\item\label{lemma_ratio_large} If $k=O(M)$, then $\mathbb{P}(\boldsymbol{S}_{\infty}=\widetilde{S})/\mathbb{P}(\boldsymbol{S}_{\infty}=S)\leq\alpha^{o(k)}(k^2/\alpha)^k$.
		\end{enumerate}

Let $\mathcal{R}$ be the set of all related pairs $(S,\widetilde{S})\in\mathcal{G}\times\mathcal{G}_k$. We define
\begin{align}
	\Sigma&:=\sum_{(S,\widetilde{S})\in\mathcal{R}}\mathbb{P}(\boldsymbol{S}_{\infty}=S),
	\\\widetilde{\Sigma}&:=\sum_{(S,\widetilde{S})\in\mathcal{R}}\mathbb{P}(\boldsymbol{S}_{\infty}=\widetilde{S}).
\end{align}
By Lemma~\ref{lemma_ratio}, we get
\begin{align}
	\widetilde{\Sigma}/\Sigma&=O((k^2/\alpha)^k),&&\mbox{if}\ k=O(1),
	\\\widetilde{\Sigma}/\Sigma&\leq\alpha^{o(k)}(k^2/\alpha)^k,&&\mbox{if}\ k=O(M).
\end{align}
By Lemma~\ref{lemma_related_good} and Lemma~\ref{lemma_related_bad}, we furthermore get
\begin{align}
	&\widetilde{\Sigma}\geq e^{-O(k)}(\alpha^2k)^k\sum_{\widetilde{S}\in\mathcal{G}_k}\mathbb{P}(\boldsymbol{S}_{\infty}=\widetilde{S})\geq e^{-O(k)}(\alpha^2k)^k\mathbb{P}(|\boldsymbol{S}_{\infty}|=\alpha-k),
	\\&\Sigma\leq e^{O(k)}(\alpha^2M/k)^k\sum_{S\in\mathcal{G}}\mathbb{P}(\boldsymbol{S}_{\infty}=S)\leq e^{O(k)}(\alpha^2M/k)^k,\ \text{so}
	\\&\mathbb{P}(|\boldsymbol{S}_{\infty}|=\alpha-k)\leq e^{O(k)}(M/k^2)^{k}\widetilde{\Sigma}/\Sigma.
\end{align}
The result follows, since $e^{O(k)}=O(1)$ if $k=O(1)$ and $e^{O(k)}=\alpha^{o(k)}$ if $k=O(M)$.

By Lemma~\ref{lemma_generalization}, we have $$\mathbb{P}(\boldsymbol{S}_{\infty}=\widetilde{S})/\mathbb{P}(\boldsymbol{S}_{\infty}=S)\leq\mathscr{E}_k\mathscr{P}_k(\widetilde{S})/\mathscr{P}(S)$$ for some error term $\mathscr{E}_k$ with $\mathscr{E}_k=O(1)$ for $k=O(1)$ and $\mathscr{E}_k\leq\alpha^{o(k)}$ for $k=O(M)$. Recall that $\widetilde{S}$ is a maximal FIS, such that $K=|V\setminus\overline{N}(\widetilde{S})|=n_k$ by Corollary~\ref{corollary_hereditary}. It thus suffices to show that $$\frac{\mathscr{P}_k(\widetilde{S})}{\mathscr{P}(S)}=\frac{\exp\left(\frac12P|R^*(\widetilde{S})|-{\bf{w}}(\widetilde{S})\right)\prod_{t=k+1}^\alpha\frac{t-k}{n_t-n_k}}{\exp\left(\frac12P|R^*(S)|-{\bf{w}}(S)\right)\prod_{t=1}^\alpha\frac{t}{n_t}}\leq e^{O(k)}\left(\frac{k^2}{\alpha}\right)^k.$$

Firstly, since $|S\setminus\widetilde{S}|=3k$ and $|\widetilde{S}\setminus S|=2k$, we have
\begin{align}
	|{\bf{w}}(S)-{\bf{w}}(\widetilde{S})|&\leq|{\bf{w}}(S\setminus\widetilde{S})|+|{\bf{w}}(\widetilde{S}\setminus S)|=O(kM/\alpha),
	\\||R^*(\widetilde{S})|-|R^*(S)||&\leq|R^*(\widetilde{S}\setminus S)|+|R^*(S\setminus\widetilde{S})|=O(kM).
\end{align}
It follows that $$\frac{\exp\left(\tfrac12P|R^*(\widetilde{S})|-{\bf{w}}(\widetilde{S})\right)}{\exp\left(\tfrac12P|R^*(S)|-{\bf{w}}(S)\right)}=e^{o(1)}.$$

Secondly, since $n_t=\tfrac{\ell}{2}t(t+\tfrac{2}{\ell}-1)$ and thus $n_t-n_k=\tfrac{\ell}{2}(t-k)(t+k+\tfrac{2}{\ell}-1)$, telescoping gives
\begin{align}
	\frac{\prod_{t=k+1}^\alpha\frac{t-k}{n_t-n_k}}{\prod_{t=1}^\alpha\frac{t}{n_t}}
	&=\frac{\prod_{t=1}^{\alpha}\frac{\ell}{2}(t+\frac{2}{\ell}-1)}{\prod_{t=k+1}^{\alpha}\frac{\ell}{2}(t+k+\frac{2}{\ell}-1)}
	\\&=\left(\frac{\ell}{2}\right)^k\frac{\prod_{i=1}^{2k}(i+\frac{2}{\ell}-1)}{\prod_{i=1}^{k}(\alpha+i+\frac{2}{\ell}-1)}
	\\&\leq\left(\frac{\ell}{2}\right)^k\frac{(2k)!}{\alpha^k}
	\\&\leq e^{O(k)}\left(\frac{k^2}{\alpha}\right)^k
\end{align}
by Stirling's approximation.
